inventory = {"tube": 3, "plate": 2}
item = input()
inventory[item] += int(input())
for key in sorted(inventory):
    print(f"{key}: {inventory[key]}")

value = int(input())
if value < 10:
    print("low")
elif value <= 20:
    print("normal")
else:
    print("high")

counts = {}
for label in input().split():
    counts[label] = counts.get(label, 0) + 1
for label in sorted(counts):
    print(f"{label}: {counts[label]}")

n = int(input())
for _ in range(n):
    line = input()
    if line == "END":
        break
    if line.startswith("#"):
        continue
    print(line)

labels = input().split()
lengths = {label: len(label) for label in labels}
distinct = {len(label) for label in labels}
for label in sorted(lengths):
    print(f"{label}:{lengths[label]}")
print("lengths: " + (" ".join(map(str, sorted(distinct))) or "none"))

